import type { CustomTextStyling, DialogueText, PlayerId, SpeechVoice } from "@bloxd"
import { clearTimeout, setTimeout, TimeoutId } from "@plugins/helpers"

/** Long enough to read most lines once they have appeared. */
const DEFAULT_DURATION_MS = 6000

export type DialogueOpts = {
	/** Shown above the line, such as a name. */
	speakerName?: string | CustomTextStyling
	/** A preset such as "regular" or "gruff", or every synth parameter. Omit for a silent line. */
	voice?: SpeechVoice
	/** How long the line stays up, counted from when it starts to appear. Defaults to 6 seconds. */
	durationMs?: number
}

const hideTimeouts: Record<PlayerId, TimeoutId> = {}

/**
 * Shows a player a line of dialogue below the crosshair for a while. A new line replaces the one already up.
 * @param playerId - The player to show the line to
 * @param text - The line. `[[Item Name]]` shows the item's icon inline
 * @param opts - The speaker's name, the voice that reads it out, and how long it stays up
 */
export function sayDialogue(playerId: PlayerId, text: DialogueText, opts: DialogueOpts = {}) {
	if (hideTimeouts[playerId] !== undefined) {
		clearTimeout(hideTimeouts[playerId])
		// Cleared first, so a line said again replays rather than matching the value already set
		api.setClientOption(playerId, "dialogue", null)
	}
	api.setClientOption(playerId, "dialogue", { line: text, speakerName: opts.speakerName, voice: opts.voice })
	hideTimeouts[playerId] = setTimeout(
		() => {
			clearDialogue(playerId)
		},
		opts.durationMs ?? DEFAULT_DURATION_MS,
		playerId,
	)
}

/**
 * Hides the line of dialogue a player is shown.
 * @param playerId - The player shown the line
 */
export function clearDialogue(playerId: PlayerId) {
	if (hideTimeouts[playerId] === undefined) {
		return
	}
	clearTimeout(hideTimeouts[playerId])
	delete hideTimeouts[playerId]
	api.setClientOption(playerId, "dialogue", null)
}

onPlayerLeave = (playerId: PlayerId) => {
	delete hideTimeouts[playerId]
}
